{"file_content": "$s = ''
function probe($name, $block){
  try { $r = & $block; $script:s += "$name=OK $r`n" } catch { $script:s += "$name=NO`n" }
}
# pandoc
try { $p = (Get-Command pandoc -ErrorAction Stop).Source; $s += "pandoc=$p`n" } catch { $s += "pandoc=NO`n" }
# wkhtmltopdf
try { $p = (Get-Command wkhtmltopdf -ErrorAction Stop).Source; $s += "wkhtmltopdf=$p`n" } catch { $s += "wkhtmltopdf=NO`n" }
# Word COM
try { $w = New-Object -ComObject Word.Application; $s += "WordCOM=OK`n"; $w.Quit() } catch { $s += "WordCOM=NO`n" }
# WPS COM
try { $k = New-Object -ComObject KWPS.Application; $s += "WPSCOM=OK`n"; $k.Quit() } catch { $s += "WPSCOM=NO`n" }
# Edge / Chrome headless
$edge = "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe"
$edge2 = "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe"
if (Test-Path $edge) { $s += "edge=$edge`n" } elseif (Test-Path $edge2) { $s += "edge=$edge2`n" } else { $s += "edge=NO`n" }
Set-Content -Path 'probe_tools.txt' -Value $s -Encoding UTF8
