  function Esc($t){ $t -replace '&','&amp;' -replace '<','&lt;' -replace '>','&gt;' }
  function Inline($t){
    $t = Esc $t
    $t = [regex]::Replace($t,'\*\*(.+?)\*\*','<b>$1</b>')
    $t = [regex]::Replace($t,'`(.+?)`','<code>$1</code>')
    return $t
  }
  foreach($raw in $lines){
    $line = $raw.TrimEnd()
    if($line -match '^```'){
      if($inCode){ [void]$sb.Append('</pre>'); $inCode=$false } else { [void]$sb.Append('<pre>'); $inCode=$true }
      continue
    }
    if($inCode){ [void]$sb.Append((Esc $raw)+"`n"); continue }
    # 表格行
    if($line -match '^\s*\|'){
      $cells = $line.Trim().Trim('|') -split '\|'
      if($line -match '^\s*\|[\s:\-\|]+\|?\s*$'){ continue } # 分隔线
      if(-not $inTable){ [void]$sb.Append('<table>'); $inTable=$true; $headerDone=$false }
      $tag = if(-not $headerDone){ 'th' } else { 'td' }
      [void]$sb.Append('<tr>')
      foreach($c in $cells){ [void]$sb.Append("<$tag>"+(Inline $c.Trim())+"</$tag>") }
      [void]$sb.Append('</tr>')
      $headerDone=$true
      continue
    } elseif($inTable){ [void]$sb.Append('</table>'); $inTable=$false }
    # 标题
    if($line -match '^(#{1,6})\s+(.*)'){
      $lvl=$matches[1].Length; [void]$sb.Append("<h$lvl>"+(Inline $matches[2])+"</h$lvl>"); continue
    }
    if($line -match '^---+\s*$'){ [void]$sb.Append('<hr>'); continue }
    if($line -match '^\s*[-*]\s+(.*)'){ [void]$sb.Append('<li>'+(Inline $matches[1])+'</li>'); continue }
    if($line -match '^\s*\d+\.\s+(.*)'){ [void]$sb.Append('<li>'+(Inline $matches[1])+'</li>'); continue }
    if($line -eq ''){ [void]$sb.Append('') ; continue }
    if($line -match '^\s*>\s?(.*)'){ [void]$sb.Append('<blockquote>'+(Inline $matches[1])+'</blockquote>'); continue }
    [void]$sb.Append('<p>'+(Inline $line)+'</p>')
  }
  if($inTable){ [void]$sb.Append('</table>') }
  if($inCode){ [void]$sb.Append('</pre>') }
  $css = '<style>body{font-family:"Microsoft YaHei",sans-serif;line-height:1.7;color:#222;padding:20px;}h1{color:#1a4d6e;border-bottom:2px solid #2c6e9b;}h2{color:#1a4d6e;background:#eef4f9;padding:6px 10px;border-left:4px solid #2c6e9b;}h3{color:#2c6e9b;}table{border-collapse:collapse;width:100%;font-size:13px;margin:10px 0;}th,td{border:1px solid #c4d3df;padding:6px 8px;text-align:left;vertical-align:top;}th{background:#2c6e9b;color:#fff;}tr:nth-child(even){background:#f5f9fc;}code{background:#f0f0f0;padding:1px 4px;}blockquote{color:#555;border-left:3px solid #ccc;padding-left:10px;margin-left:0;}pre{background:#f6f8fa;border:1px solid #ddd;padding:10px;}</style>'
  $html = '<!DOCTYPE html><html><head><meta charset="UTF-8">'+$css+'</head><body>'+$sb.ToString()+'</body></html>'
  Set-Content -Path $htmlPath -Value $html -Encoding UTF8
}

